//! Rendering and writing the engine's `models.yml`.
//!
//! The file never contains a secret - `apiKey` holds the *name* of the environment variable the
//! host injects at spawn time - and only the `providers` root key is written, because the schema
//! rejects unknown root keys. A file that fails validation makes the engine drop *every* custom
//! provider, so a value that cannot be read back verbatim is quoted instead of written raw.

use std::path::Path;

use crate::errors::{IpcError, IpcResult, STORE_UNAVAILABLE};
use crate::models::agent::CustomProvider;

/// The generated file's first line: a file without it is not ours, and is backed up before we
/// take it over.
pub(super) const MANAGED_MARKER: &str = "# omp-desktop managed";

pub(super) const MODELS_FILE: &str = "models.yml";

pub(super) async fn write_models_yml_blocking(
    agent_dir: &Path,
    providers: Vec<CustomProvider>,
) -> IpcResult<Vec<CustomProvider>> {
    let directory = agent_dir.to_path_buf();
    let to_write = providers.clone();
    tauri::async_runtime::spawn_blocking(move || write_models_yml(&directory, &to_write))
        .await
        .map_err(|_| task_failed())??;
    Ok(providers)
}

fn task_failed() -> IpcError {
    IpcError::new(
        crate::errors::STORE_UNAVAILABLE,
        "The custom provider task failed.",
    )
}

/// Renders and writes `models.yml`. Only `providers` is written; a file we did not create is
/// backed up once before being replaced.
pub(crate) fn write_models_yml(agent_dir: &Path, providers: &[CustomProvider]) -> IpcResult<()> {
    let path = agent_dir.join(MODELS_FILE);
    let contents = render_models_yml(providers);
    std::fs::create_dir_all(agent_dir).map_err(|_| write_failed())?;

    let existing = std::fs::read_to_string(&path).ok();
    if let Some(existing) = existing.as_deref() {
        if !existing.trim().is_empty() && !existing.starts_with(MANAGED_MARKER) {
            let backup = agent_dir.join(format!("{MODELS_FILE}.omp-desktop.bak"));
            if !backup.exists() {
                std::fs::copy(&path, &backup).map_err(|_| write_failed())?;
                crate::services::log::warn(&format!(
                    "existing {} was not generated by this app; backed up before replacing",
                    path.display()
                ));
            }
        }
    }

    // A temporary file in the same directory plus a rename: the engine either reads the previous
    // file or the complete new one, never a half-written provider list.
    let temporary = agent_dir.join(format!("{MODELS_FILE}.tmp-{}", std::process::id()));
    std::fs::write(&temporary, contents).map_err(|_| write_failed())?;
    std::fs::rename(&temporary, &path).map_err(|_| {
        let _ = std::fs::remove_file(&temporary);
        write_failed()
    })
}

pub(super) fn render_models_yml(providers: &[CustomProvider]) -> String {
    let mut out = String::from(MANAGED_MARKER);
    out.push('\n');
    if providers.is_empty() {
        // Keep the managed marker so the next write does not back this file up again.
        out.push_str("providers: {}\n");
        return out;
    }
    out.push_str("providers:\n");
    for provider in providers {
        out.push_str(&format!("  {}:\n", provider.input.id));
        out.push_str(&format!(
            "    baseUrl: {}\n",
            yaml_scalar(&provider.input.base_url)
        ));
        out.push_str(&format!("    api: {}\n", yaml_scalar(&provider.input.api)));
        if provider.api_key_masks.len() > 1 {
            // A rotation pool cannot be named by one environment variable, and the schema refuses
            // `auth: apiKey` without one. `auth: none` is the only keyless spelling the schema
            // accepts; it is not keyless in practice, because the host installs a stored credential
            // row per key and the engine resolves the provider as `api_key` while one exists.
            out.push_str("    auth: none\n");
        } else if provider.api_key_configured {
            // The engine treats this as an environment variable name first, which is exactly how
            // the host injects the real key at spawn time.
            out.push_str(&format!("    apiKey: {}\n", provider.key_env));
        } else {
            out.push_str("    auth: none\n");
        }
        if !provider.input.models.is_empty() {
            out.push_str("    models:\n");
            for model in &provider.input.models {
                out.push_str(&format!("      - id: {}\n", yaml_scalar(&model.id)));
                out.push_str(&format!("        name: {}\n", yaml_scalar(&model.name)));
                out.push_str(&format!(
                    "        input: {}\n",
                    if model.supports_images {
                        "[text, image]"
                    } else {
                        "[text]"
                    }
                ));
                // The schema requires these to be positive when present, so an unknown value is
                // omitted instead of written as zero.
                if model.context_window > 0 {
                    out.push_str(&format!(
                        "        contextWindow: {}\n",
                        model.context_window
                    ));
                }
                if model.max_tokens > 0 {
                    out.push_str(&format!("        maxTokens: {}\n", model.max_tokens));
                }
                // Written either way, never omitted. A missing `reasoning` is not "false" to the
                // engine: `finalizeCustomModel` (pi-coding-agent `config/custom-models`) falls back
                // to the bundled catalogue entry with the same id, and that lookup is
                // provider-agnostic - a custom model whose id a bundled provider also carries
                // inherits *its* `reasoning: true`, so the composer offered an effort ladder the
                // user had explicitly unchecked (2026-10-29, user report). The explicit `false`
                // is the only way that answer is not overwritten downstream.
                out.push_str(&format!(
                    "        reasoning: {}\n",
                    model.supports_reasoning
                ));
            }
        }
    }
    out
}

/// YAML scalar writer.
///
/// A value is written bare only when it is provably a plain string: an unquoted value the reader
/// would parse as a number, a boolean or a null - or one carrying a control character - invalidates
/// the whole file, and a file that fails validation makes the engine drop *every* custom provider,
/// not just the offending entry.
fn yaml_scalar(value: &str) -> String {
    if is_plain_yaml_string(value) {
        return value.to_owned();
    }
    let mut quoted = String::with_capacity(value.len() + 2);
    quoted.push('"');
    for character in value.chars() {
        match character {
            '"' => quoted.push_str("\\\""),
            '\\' => quoted.push_str("\\\\"),
            '\n' => quoted.push_str("\\n"),
            '\r' => quoted.push_str("\\r"),
            '\t' => quoted.push_str("\\t"),
            other if other.is_control() => quoted.push_str(&format!("\\x{:02x}", other as u32)),
            other => quoted.push(other),
        }
    }
    quoted.push('"');
    quoted
}

/// True when `value` can be written without quotes and still read back as the same string.
fn is_plain_yaml_string(value: &str) -> bool {
    const RESERVED: &[&str] = &[
        "true", "false", "null", "yes", "no", "on", "off", "~", "nan", "inf", "infinity", "-inf",
    ];
    if value.is_empty() || value.len() > 512 {
        return false;
    }
    let plain = value.chars().all(|character| {
        character.is_ascii_alphanumeric() || matches!(character, '.' | '_' | '/' | '-' | '+' | ':')
    });
    if !plain {
        return false;
    }
    // A value starting with a sign, a digit or a dot may be read as a number: `123`, `2.5`,
    // `1e5`, `0x1f`, `1:30`, `0123`, `_1` all have to be quoted.
    let numeric_looking = value.starts_with(|character: char| {
        character.is_ascii_digit() || matches!(character, '+' | '-' | '.' | '_')
    });
    if numeric_looking {
        let numeric = value.parse::<f64>().is_ok()
            || value
                .chars()
                .all(|character| character.is_ascii_digit() || character == '_')
            || value.contains(':')
            || value.to_ascii_lowercase().contains("0x");
        if numeric {
            return false;
        }
    }
    if value.ends_with(':') {
        return false;
    }
    !RESERVED.contains(&value.to_ascii_lowercase().as_str())
}

fn write_failed() -> IpcError {
    IpcError::new(
        STORE_UNAVAILABLE,
        "The engine model configuration could not be written.",
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::models::agent::{CustomModelDefinition, CustomProvider, CustomProviderInput};
    use crate::services::custom_providers::key_env;

    fn model(id: &str) -> CustomModelDefinition {
        CustomModelDefinition {
            id: id.to_owned(),
            name: id.to_owned(),
            context_window: 128_000,
            max_tokens: 8192,
            supports_images: false,
            supports_reasoning: false,
        }
    }

    fn provider(id: &str, api_key_configured: bool) -> CustomProvider {
        CustomProvider {
            input: CustomProviderInput {
                id: id.to_owned(),
                name: "My Gateway".to_owned(),
                base_url: "https://api.example.com/v1".to_owned(),
                api: "openai-completions".to_owned(),
                models: vec![model("gpt-x")],
            },
            key_env: key_env(id),
            api_key_configured,
            api_key_masks: if api_key_configured {
                vec!["sk-*****abcd".to_owned()]
            } else {
                Vec::new()
            },
        }
    }

    /// The generated file is the engine's input: only `providers`, the key variable name (never a
    /// secret), and limits the schema accepts.
    #[test]
    fn the_generated_models_file_matches_the_engine_schema() {
        let rendered = render_models_yml(&[provider("my-gateway", true)]);
        assert!(rendered.starts_with(MANAGED_MARKER));
        assert!(rendered.contains("providers:\n"));
        assert!(rendered.contains("  my-gateway:\n"));
        assert!(rendered.contains("    baseUrl: https://api.example.com/v1\n"));
        assert!(rendered.contains("    api: openai-completions\n"));
        assert!(rendered.contains("    apiKey: OMP_DESKTOP_CUSTOM_MY_GATEWAY_API_KEY\n"));
        assert!(
            !rendered.contains("sk-"),
            "the file must never carry a secret"
        );
        assert!(rendered.contains("        contextWindow: 128000\n"));
        assert!(rendered.contains("        maxTokens: 8192\n"));
        assert!(rendered.contains("        input: [text]\n"));
    }

    /// Both answers are written. Omitting `false` let the engine's provider-agnostic catalogue
    /// lookup lend a same-id bundled model's `reasoning: true` back to a custom model that does not
    /// think (2026-10-29, user report), so the unchecked box has to be stated in the file.
    #[test]
    fn reasoning_is_written_in_both_directions() {
        let plain = render_models_yml(&[provider("edge", true)]);
        assert!(plain.contains("        reasoning: false\n"));

        let mut thinking = provider("edge", true);
        thinking.input.models[0].supports_reasoning = true;
        let thinking = render_models_yml(&[thinking]);
        assert!(thinking.contains("        reasoning: true\n"));
    }

    #[test]
    fn a_provider_without_a_key_uses_auth_none() {
        let rendered = render_models_yml(&[provider("edge", false)]);
        assert!(rendered.contains("    auth: none\n"));
        assert!(!rendered.contains("apiKey:"));
    }

    /// A rotation pool has no single environment variable to name, and the schema refuses
    /// `auth: apiKey` without one; `auth: none` plus the host's stored rows is the accepted shape.
    #[test]
    fn a_multi_key_provider_pins_auth_without_a_variable() {
        let mut entry = provider("edge", true);
        entry.api_key_masks = vec!["a*****b".to_owned(); 3];
        let rendered = render_models_yml(&[entry]);
        assert!(rendered.contains("    auth: none\n"));
        assert!(!rendered.contains("apiKey:"));
    }

    /// Zero is not a legal value for these fields, so an unknown limit is omitted instead.
    #[test]
    fn unknown_limits_are_omitted_instead_of_written_as_zero() {
        let mut entry = provider("edge", true);
        entry.input.models[0].context_window = 0;
        entry.input.models[0].max_tokens = 0;
        entry.input.models[0].supports_images = true;
        let rendered = render_models_yml(&[entry]);
        assert!(!rendered.contains("contextWindow"));
        assert!(!rendered.contains("maxTokens"));
        assert!(rendered.contains("        input: [text, image]\n"));
    }

    #[test]
    fn an_empty_registry_still_produces_a_valid_file() {
        let rendered = render_models_yml(&[]);
        assert_eq!(rendered, format!("{MANAGED_MARKER}\nproviders: {{}}\n"));
    }

    /// Values the engine's YAML reader could misinterpret are quoted.
    #[test]
    fn yaml_scalars_are_quoted_when_they_are_not_plain_words() {
        assert_eq!(yaml_scalar("gpt-x"), "gpt-x");
        assert_eq!(yaml_scalar("zai-org/GLM-5.3"), "zai-org/GLM-5.3");
        assert_eq!(yaml_scalar("true"), "\"true\"");
        assert_eq!(yaml_scalar("with space"), "\"with space\"");
        assert_eq!(yaml_scalar(""), "\"\"");
        for numeric in [
            "123", "2.5", "-3", "+4", "1e5", "0x1f", "1:30", "0123", ".5", "1_000",
        ] {
            let rendered = yaml_scalar(numeric);
            assert!(
                rendered.starts_with('"') && rendered.ends_with('"'),
                "{numeric} must be quoted, got {rendered}"
            );
        }
        assert_eq!(yaml_scalar("a\nb"), "\"a\\nb\"");
        assert_eq!(yaml_scalar("a\tb"), "\"a\\tb\"");
        assert_eq!(yaml_scalar("a\u{7}b"), "\"a\\x07b\"");
        assert_eq!(yaml_scalar("say \"hi\""), "\"say \\\"hi\\\"\"");
    }

    /// A value that cannot be represented verbatim must not add a line, which would break the
    /// file or inject a sibling of `providers`.
    #[test]
    fn hostile_values_stay_inside_their_provider_entry() {
        let mut entry = provider("hostile", true);
        entry.input.models[0].id = "a\nproviders:\n  injected: yes".to_owned();
        entry.input.models[0].name = "123".to_owned();
        entry.input.base_url = "https://api.example.com/v1#frag \"quoted\"".to_owned();
        let rendered = render_models_yml(&[entry]);

        for line in rendered.lines().skip(1) {
            assert!(
                line.starts_with(' ') || line == "providers:",
                "only `providers:` may start at column zero, saw {line:?}"
            );
        }
        assert!(
            !rendered
                .lines()
                .any(|line| line.trim_start().starts_with("injected:")),
            "the injected key must stay inside a quoted scalar: {rendered}"
        );
        assert!(
            rendered.contains("\\nproviders:"),
            "the escape must be literal: {rendered}"
        );
        assert!(rendered.contains("        name: \"123\"\n"));
        assert_eq!(
            rendered.matches("      - id:").count(),
            1,
            "the hostile id must not produce a second model entry"
        );
    }
}
